//! Integration tests for `POST /admin/bootstrap`.
//!
//! Exercises the dry-run path (no LLM required) end-to-end through the
//! axum router: marshal a synthetic [`BootstrapSource`] bundle, POST it
//! to the router, and assert the response shape matches [`BootstrapOutcome`].
//! The LLM path is covered by the consolidate-crate unit tests.

use ai_memory_consolidate::{BootstrapOutcome, BootstrapSource, SourceKind};
use ai_memory_core::repository_identity::{IdentitySource, IdentityStyle, RepositoryIdentity};
use ai_memory_llm::{ChatRequest, ChatResponse, LlmProvider};
use ai_memory_mcp::{AdminState, admin_router};
use ai_memory_store::{DecayParams, Store};
use ai_memory_wiki::Wiki;
use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::json;
use std::sync::Arc;
use tempfile::TempDir;
use tower::ServiceExt;

struct EmptyBootstrapLlm;

#[async_trait::async_trait]
impl LlmProvider for EmptyBootstrapLlm {
    fn name(&self) -> &'static str {
        "empty-bootstrap"
    }

    fn model(&self) -> &str {
        "empty-bootstrap"
    }

    async fn complete(&self, _request: ChatRequest) -> ai_memory_llm::LlmResult<ChatResponse> {
        unreachable!("bootstrap uses structured completion")
    }

    async fn complete_structured_raw(
        &self,
        _request: ChatRequest,
        _schema: serde_json::Value,
    ) -> ai_memory_llm::LlmResult<serde_json::Value> {
        Ok(json!({ "pages": [], "rationale": "ok" }))
    }
}

/// Build a minimal `AdminState` backed by a real on-disk store + wiki.
async fn make_admin_state(tmp: &TempDir) -> AdminState {
    let store = Store::open(tmp.path()).unwrap();
    let wiki = Wiki::new(tmp.path(), store.writer.clone())
        .unwrap()
        .with_store_reader(store.reader.clone());
    let db_path = store.db_path().to_path_buf();
    AdminState {
        ingest_metrics: std::sync::Arc::new(ai_memory_core::IngestMetrics::default()),
        mcp_metrics: std::sync::Arc::new(ai_memory_mcp::McpMetrics::default()),
        writer: store.writer.clone(),
        reader: store.reader.clone(),
        wiki,
        llm: None, // no LLM — bootstrap report path only
        auto_improve_require_approval: false,
        auto_improve_review_config: Default::default(),
        embedder: None,
        provider_health: ai_memory_llm::ProviderHealth::default(),
        decay_params: DecayParams::default(),
        contradiction_band_min: ai_memory_consolidate::DEFAULT_CONTRADICTION_SIM_LOW,
        contradiction_band_max: ai_memory_consolidate::DEFAULT_CONTRADICTION_SIM_HIGH,
        data_dir: tmp.path().to_path_buf(),
        db_path,
        bind: "127.0.0.1:0".to_string(),
        home_dir: None,
        bootstrap_lock: std::sync::Arc::new(tokio::sync::Mutex::new(())),
        token_pepper: None,
        active_project: ai_memory_core::ActiveProject::new(),
        scope_invalidator: None,
        trusted_proxy_identity: false,
    }
}

/// Synthetic sources that represent a small project.
fn synthetic_sources() -> Vec<BootstrapSource> {
    vec![
        BootstrapSource {
            kind: SourceKind::Readme,
            label: "README (README.md)".into(),
            text: "# my-project\n\nA toy project used for testing bootstrap ingestion.".into(),
        },
        BootstrapSource {
            kind: SourceKind::ProjectRules,
            label: "rules: CLAUDE.md".into(),
            text: "## Rules\n\n- Always write tests first.\n- Prefer composition.".into(),
        },
        BootstrapSource {
            kind: SourceKind::GitCommit,
            label: "git: feat: add initial storage layer".into(),
            text: "Commit abc12345\nAuthor: Test\nDate: 2026-01-01\n\nfeat: add initial storage layer\n\nAdded SQLite-backed store with WAL mode.".into(),
        },
    ]
}

/// POST a JSON body to the admin router and return the response.
async fn post_bootstrap(state: AdminState, body: serde_json::Value) -> axum::response::Response {
    let router = admin_router(state);
    let req = Request::builder()
        .method("POST")
        .uri("/admin/bootstrap")
        .header("content-type", "application/json")
        .body(Body::from(serde_json::to_vec(&body).unwrap()))
        .unwrap();
    router.oneshot(req).await.unwrap()
}

/// Dry-run with no LLM returns a valid [`BootstrapOutcome`] with
/// `dry_run: true` and no pages written.
#[tokio::test]
async fn dry_run_returns_outcome_without_llm() {
    let tmp = TempDir::new().unwrap();
    let state = make_admin_state(&tmp).await;

    let body = json!({
        "workspace": "test-ws",
        "project": "test-proj",
        "sources": synthetic_sources(),
        "max_input_tokens": 50_000,
        "dry_run": true,
        "force": false,
    });

    let resp = post_bootstrap(state, body).await;
    assert_eq!(resp.status(), StatusCode::OK);

    let bytes = axum::body::to_bytes(resp.into_body(), usize::MAX)
        .await
        .unwrap();
    let outcome: BootstrapOutcome = serde_json::from_slice(&bytes).unwrap();

    assert!(outcome.dry_run, "must be a dry-run outcome");
    assert_eq!(outcome.pages_written.len(), 0, "dry-run writes no pages");
    assert_eq!(outcome.sources_collected, 3, "three sources were supplied");
    assert!(outcome.sources_sent <= outcome.sources_collected);
    assert_eq!(outcome.llm_chunks, 1, "small bundle fits one chunk");
}

/// Client-side pre-prune count is preserved in the outcome.
#[tokio::test]
async fn dry_run_honours_sources_collected_hint() {
    let tmp = TempDir::new().unwrap();
    let state = make_admin_state(&tmp).await;

    let body = json!({
        "workspace": "test-ws",
        "project": "test-proj",
        "sources": synthetic_sources(),
        "sources_collected": 9_999,
        "max_input_tokens": 50_000,
        "dry_run": true,
    });

    let resp = post_bootstrap(state, body).await;
    assert_eq!(resp.status(), StatusCode::OK);
    let bytes = axum::body::to_bytes(resp.into_body(), usize::MAX)
        .await
        .unwrap();
    let outcome: BootstrapOutcome = serde_json::from_slice(&bytes).unwrap();
    assert_eq!(outcome.sources_collected, 9_999);
    assert_eq!(
        outcome.sources_dropped,
        9_999 - outcome.sources_sent,
        "dropped must be collected minus sent"
    );
}

/// When no LLM is configured and `dry_run=false`, the server returns
/// 503 with a descriptive error body — not a panic.
#[tokio::test]
async fn bootstrap_surfaces_manifest_failure_after_promotion() {
    let tmp = TempDir::new().unwrap();
    let mut state = make_admin_state(&tmp).await;
    state.llm = Some(Arc::new(EmptyBootstrapLlm));
    let workspace = state
        .writer
        .get_or_create_workspace("default")
        .await
        .unwrap();
    let (project, _) = state
        .writer
        .resolve_project_by_identity(
            workspace,
            RepositoryIdentity {
                identity: "github.com/acme/api".into(),
                source: IdentitySource::GitRemote,
            },
            IdentityStyle::HostPath,
            "api",
            None,
            None,
            None,
        )
        .await
        .unwrap();
    state.wiki.backfill_scope_manifests().await.unwrap();
    let manifest = tmp
        .path()
        .join("wiki")
        .join(workspace.to_string())
        .join(project.to_string())
        .join("_meta.md");
    std::fs::remove_file(&manifest).unwrap();
    std::fs::create_dir(&manifest).unwrap();

    let resp = post_bootstrap(
        state,
        json!({
            "workspace": "default", "project": "acme-api", "sources": synthetic_sources(),
            "max_input_tokens": 50_000, "dry_run": false, "force": true
        }),
    )
    .await;
    assert_eq!(resp.status(), StatusCode::OK);
    let bytes = axum::body::to_bytes(resp.into_body(), usize::MAX)
        .await
        .unwrap();
    let outcome: BootstrapOutcome = serde_json::from_slice(&bytes).unwrap();
    assert!(
        outcome
            .manifest_warning
            .as_deref()
            .is_some_and(|warning| warning.contains("committed"))
    );
}

#[tokio::test]
async fn non_dry_run_without_llm_returns_503() {
    let tmp = TempDir::new().unwrap();
    let state = make_admin_state(&tmp).await;

    let body = json!({
        "workspace": "test-ws",
        "project": "test-proj",
        "sources": synthetic_sources(),
        "max_input_tokens": 50_000,
        "dry_run": false,
        "force": false,
    });

    let resp = post_bootstrap(state, body).await;
    assert_eq!(resp.status(), StatusCode::SERVICE_UNAVAILABLE);

    let bytes = axum::body::to_bytes(resp.into_body(), usize::MAX)
        .await
        .unwrap();
    let val: serde_json::Value = serde_json::from_slice(&bytes).unwrap();
    let error_msg = val["error"].as_str().unwrap_or("");
    assert!(
        error_msg.contains("LLM") || error_msg.contains("provider"),
        "error message must mention LLM/provider: {error_msg}"
    );
}

/// Empty source list returns an error — the server must not panic or
/// produce a misleading success response.
#[tokio::test]
async fn empty_sources_returns_error() {
    let tmp = TempDir::new().unwrap();
    let state = make_admin_state(&tmp).await;

    let body = json!({
        "workspace": "test-ws",
        "project": "test-proj",
        "sources": [],
        "dry_run": true,
    });

    let resp = post_bootstrap(state, body).await;
    // Empty sources with dry_run=true goes through process_sources which
    // returns BootstrapError::NoSources -> UNPROCESSABLE_ENTITY.
    assert_ne!(
        resp.status(),
        StatusCode::OK,
        "empty sources must not succeed"
    );
}

/// A non-empty request that gets fully pruned by an impossibly small budget is
/// still a validation failure, not a successful no-op bootstrap.
#[tokio::test]
async fn fully_pruned_sources_return_error() {
    let tmp = TempDir::new().unwrap();
    let state = make_admin_state(&tmp).await;

    let body = json!({
        "workspace": "test-ws",
        "project": "test-proj",
        "sources": synthetic_sources(),
        "max_input_tokens": 1,
        "dry_run": true,
    });

    let resp = post_bootstrap(state, body).await;
    assert_eq!(resp.status(), StatusCode::UNPROCESSABLE_ENTITY);
}

/// The workspace + project are auto-created by the handler; posting the
/// same workspace/project a second time with `force=true` must not error
/// (idempotent upsert).
#[tokio::test]
async fn workspace_and_project_auto_created_idempotent() {
    let tmp = TempDir::new().unwrap();
    let state = make_admin_state(&tmp).await;

    let body = json!({
        "workspace": "idempotent-ws",
        "project": "idempotent-proj",
        "sources": synthetic_sources(),
        "dry_run": true,
        "force": true,
    });

    // First call.
    let resp1 = post_bootstrap(state.clone(), body.clone()).await;
    assert_eq!(resp1.status(), StatusCode::OK);

    // Second call — workspace + project already exist; must still succeed.
    let resp2 = post_bootstrap(state, body).await;
    assert_eq!(resp2.status(), StatusCode::OK);
}

//! `memory_restore_page` through the production auth stack.
//!
//! Git keeps every version the live wiki dropped: a page a root deleted, a
//! session purge removed, an expired page the forget sweep hard-deleted. The
//! tool's listing names those versions and a restore brings their text back,
//! so both carry the authority of root-only `/admin/restore-page`. These tests
//! drive the real `require_bearer` middleware with real `aim_` DB-user tokens
//! and the trusted-proxy rung, attempt each bypass, and keep a root control
//! beside every refusal so a blanket deny cannot pass for the guard.

use ai_memory_core::{ActorContext, ApiCredentialId, NewUser, ProjectId, UserRole};
use ai_memory_mcp::AiMemoryServer;
use ai_memory_mcp::auth::{AuthState, require_bearer};
use ai_memory_store::{AccessMode, GrantLevel, Store, TokenPepper, generate_api_key, hash_token};
use ai_memory_wiki::Wiki;
use axum::Router;
use axum::body::Body;
use axum::http::Request;
use rmcp::transport::streamable_http_server::session::local::LocalSessionManager;
use rmcp::transport::streamable_http_server::{StreamableHttpServerConfig, StreamableHttpService};
use serde_json::{Value, json};
use std::sync::Arc;
use tempfile::TempDir;
use tower::ServiceExt;

const ROOT_TOKEN: &str = "the-root-token";
const PROXY_TOKEN: &str = "the-proxy-token";
const PEPPER: &str = "test-pepper-restore-page-authz-123456789";
const ISSUER: &str = "https://idp.example";
const ALICE_SUB: &str = "oidc-subject-alice";

struct Harness {
    http: Router,
    store: Store,
    shared: ProjectId,
    _tmp: TempDir,
}

/// A multi-user server: root bearer, `aim_` DB users, a trusted proxy, and
/// per-user slots on. `shared` is open to every user, `secret` is restricted.
async fn harness() -> Harness {
    let tmp = TempDir::new().expect("tempdir");
    let store = Store::open(tmp.path()).expect("store");
    let ws = store
        .writer
        .get_or_create_workspace("default")
        .await
        .expect("ws");
    let baked = store
        .writer
        .get_or_create_project(ws, "scratch", None)
        .await
        .expect("baked");
    let shared = store
        .writer
        .get_or_create_project(ws, "shared", None)
        .await
        .expect("shared");
    let secret = store
        .writer
        .get_or_create_project(ws, "secret", None)
        .await
        .expect("secret");
    store
        .writer
        .set_access_mode(secret, AccessMode::Restricted)
        .await
        .expect("restrict secret");
    let wiki = Wiki::new(tmp.path(), store.writer.clone()).expect("wiki");
    let server = AiMemoryServer::new(store.reader.clone(), store.writer.clone(), ws, baked)
        .with_wiki(wiki)
        .with_per_user_slots(true)
        .with_trusted_proxy_identity(true);
    let service = StreamableHttpService::new(
        move || Ok(server.clone()),
        LocalSessionManager::default().into(),
        StreamableHttpServerConfig::default()
            .with_stateful_mode(false)
            .with_json_response(true),
    );
    let auth = AuthState::new(Some(ROOT_TOKEN.to_string()))
        .with_root_actor(ActorContext {
            user: Some("dj".to_string()),
            ..ActorContext::default()
        })
        .with_trusted_proxy_bearer(PROXY_TOKEN)
        .with_multiuser(
            TokenPepper::new(PEPPER),
            store.reader.clone(),
            store.writer.clone(),
        );
    let http =
        Router::new()
            .nest_service("/mcp", service)
            .layer(axum::middleware::from_fn_with_state(
                Arc::new(auth),
                require_bearer,
            ));
    Harness {
        http,
        store,
        shared,
        _tmp: tmp,
    }
}

/// Mint a DB user with an `aim_` token; `write_on` grants write on a project.
async fn db_user(h: &Harness, username: &str, write_on: Option<ProjectId>) -> String {
    let token = [REDACTED]"token");
    let id = h
        .store
        .writer
        .create_human_user(
            NewUser {
                username: username.into(),
                name: None,
                email: None,
            },
            UserRole::User,
            None,
            false,
        )
        .await
        .expect("user");
    h.store
        .writer
        .create_api_credential(
            ApiCredentialId::new(),
            id,
            "test".into(),
            hash_token(&token, &TokenPepper::new(PEPPER)),
            None,
        )
        .await
        .expect("credential");
    if let Some(project) = write_on {
        h.store
            .writer
            .grant_memory(id, project, GrantLevel::Write, None)
            .await
            .expect("grant");
    }
    token
}

/// The raw JSON-RPC outcome: `Ok` is the tool's JSON payload, `Err` the
/// refusal message (JSON-RPC error or an `isError` tool result).
async fn call(
    router: &Router,
    bearer: &str,
    name: &str,
    arguments: Value,
) -> Result<Value, String> {
    call_with(
        router,
        &[("authorization", &format!("Bearer {bearer}"))],
        name,
        arguments,
    )
    .await
}

async fn call_with(
    router: &Router,
    headers: &[(&str, &str)],
    name: &str,
    arguments: Value,
) -> Result<Value, String> {
    let body = json!({
        "jsonrpc": "2.0",
        "id": 1,
        "method": "tools/call",
        "params": { "name": name, "arguments": arguments },
    });
    let mut req = Request::builder()
        .method("POST")
        .uri("/mcp")
        .header("host", "localhost")
        .header("content-type", "application/json")
        .header("accept", "application/json, text/event-stream");
    for (k, v) in headers {
        req = req.header(*k, *v);
    }
    let resp = router
        .clone()
        .oneshot(req.body(Body::from(body.to_string())).expect("mcp req"))
        .await
        .expect("oneshot");
    let status = resp.status();
    let bytes = axum::body::to_bytes(resp.into_body(), 4_000_000)
        .await
        .expect("body");
    let text = String::from_utf8(bytes.to_vec()).expect("utf8");
    if !status.is_success() {
        return Err(format!("HTTP {status}: {text}"));
    }
    let v: Value = serde_json::from_str(&text).unwrap_or_else(|e| panic!("non-JSON: {text}: {e}"));
    if let Some(err) = v.get("error") {
        return Err(err.to_string());
    }
    let joined = v
        .pointer("/result/content")
        .and_then(|c| c.as_array())
        .unwrap_or_else(|| panic!("missing result.content: {text}"))
        .iter()
        .filter_map(|i| i.get("text").and_then(|t| t.as_str()))
        .collect::<Vec<_>>()
        .join("\n");
    if v.pointer("/result/isError").and_then(Value::as_bool) == Some(true) {
        return Err(joined);
    }
    Ok(serde_json::from_str(&joined)
        .unwrap_or_else(|e| panic!("tool text not JSON: {joined}: {e}")))
}

fn scoped(project: &str, extra: Value) -> Value {
    let mut args = json!({ "workspace": "default", "project": project });
    if let (Some(map), Value::Object(extra)) = (args.as_object_mut(), extra) {
        map.extend(extra);
    }
    args
}

/// Root writes then deletes `path` in `project`; returns the pre-delete rev
/// root's own listing names, so a refused caller is handed a valid rev.
async fn written_then_deleted(h: &Harness, project: &str, path: &str, body: &str) -> String {
    call(
        &h.http,
        ROOT_TOKEN,
        "memory_write_page",
        scoped(project, json!({ "path": path, "body": body })),
    )
    .await
    .expect("root write");
    call(
        &h.http,
        ROOT_TOKEN,
        "memory_delete_page",
        scoped(project, json!({ "path": path })),
    )
    .await
    .expect("root delete");
    pre_delete_rev(h, project, path).await
}

async fn pre_delete_rev(h: &Harness, project: &str, path: &str) -> String {
    let listed = call(
        &h.http,
        ROOT_TOKEN,
        "memory_restore_page",
        scoped(project, json!({ "path": path })),
    )
    .await
    .expect("root lists checkpoints");
    listed["checkpoints"][1]["rev"]
        .as_str()
        .unwrap_or_else(|| panic!("write and delete checkpoints: {listed}"))
        .to_owned()
}

async fn root_reads(h: &Harness, project: &str, path: &str) -> Option<String> {
    call(
        &h.http,
        ROOT_TOKEN,
        "memory_read_page",
        scoped(project, json!({ "path": path })),
    )
    .await
    .ok()
    .and_then(|page| page["body"].as_str().map(str::to_owned))
}

/// A DB user who may WRITE the project still cannot list its checkpoints or
/// restore a version a root deleted. Root, the control, can do both.
#[tokio::test]
async fn a_db_user_with_a_write_grant_cannot_list_or_restore() {
    let h = harness().await;
    let alice = db_user(&h, "alice", Some(h.shared)).await;
    let rev = written_then_deleted(
        &h,
        "shared",
        "notes/removed.md",
        "# Removed\n\nroot-deleted text",
    )
    .await;

    // Alice's grant is real: an ordinary write in the project succeeds.
    call(
        &h.http,
        &alice,
        "memory_write_page",
        scoped(
            "shared",
            json!({ "path": "notes/alice.md", "body": "# Alice\n\nmine" }),
        ),
    )
    .await
    .expect("a write grant lets alice write");

    let listed = call(
        &h.http,
        &alice,
        "memory_restore_page",
        scoped("shared", json!({ "path": "notes/removed.md" })),
    )
    .await;
    assert!(
        listed.is_err(),
        "a DB user must not list checkpoints: {listed:?}"
    );
    let restored = call(
        &h.http,
        &alice,
        "memory_restore_page",
        scoped("shared", json!({ "path": "notes/removed.md", "rev": rev })),
    )
    .await;
    assert!(
        restored.is_err(),
        "a DB user must not restore: {restored:?}"
    );
    assert_eq!(
        root_reads(&h, "shared", "notes/removed.md").await,
        None,
        "the refused restore must not have written anything"
    );

    // Control: root restores the same rev.
    let restored = call(
        &h.http,
        ROOT_TOKEN,
        "memory_restore_page",
        scoped("shared", json!({ "path": "notes/removed.md", "rev": rev })),
    )
    .await
    .expect("root restores");
    assert_eq!(restored["restored_from"], rev.as_str());
    assert!(
        root_reads(&h, "shared", "notes/removed.md")
            .await
            .is_some_and(|body| body.contains("root-deleted text"))
    );
}

/// A restricted project the caller holds no grant on: neither listing nor
/// restoring reaches it, while root's control succeeds. An unknown bearer is
/// refused at the door.
#[tokio::test]
async fn a_foreign_restricted_project_is_refused_without_a_grant() {
    let h = harness().await;
    let mallory = db_user(&h, "mallory", Some(h.shared)).await;
    let rev = written_then_deleted(&h, "secret", "notes/plan.md", "# Plan\n\nsecret text").await;

    for args in [
        scoped("secret", json!({ "path": "notes/plan.md" })),
        scoped("secret", json!({ "path": "notes/plan.md", "rev": rev })),
    ] {
        let out = call(&h.http, &mallory, "memory_restore_page", args.clone()).await;
        let refused = out.expect_err("a foreign restricted project must be refused");
        assert!(
            !refused.contains("secret text") && !refused.contains("Plan"),
            "the refusal must not leak the version: {refused}"
        );
        let out = call(&h.http, "aim_not-a-real-token", "memory_restore_page", args).await;
        assert!(out.is_err(), "an unknown bearer must be refused: {out:?}");
    }
    assert_eq!(root_reads(&h, "secret", "notes/plan.md").await, None);

    call(
        &h.http,
        ROOT_TOKEN,
        "memory_restore_page",
        scoped("secret", json!({ "path": "notes/plan.md", "rev": rev })),
    )
    .await
    .expect("root restores in the restricted project");
    assert!(
        root_reads(&h, "secret", "notes/plan.md")
            .await
            .is_some_and(|body| body.contains("secret text"))
    );
}

/// Per-user slots: an operator's slot write lands in their own namespace.
/// The operator cannot restore it through this tool (restore is admin-only,
/// even for their own slot). Root restores the exact namespaced path, and
/// it is not re-homed into root's namespace or onto the shared slot that
/// reaches every operator's brief.
#[tokio::test]
async fn a_personal_slot_restores_to_its_exact_path_and_only_for_root() {
    let h = harness().await;
    let alice = [
        ("authorization", "Bearer the-proxy-token"),
        ("x-memory-actor-issuer", ISSUER),
        ("x-memory-actor-sub", ALICE_SUB),
    ];
    let written = call_with(
        &h.http,
        &alice,
        "memory_write_page",
        scoped(
            "scratch",
            json!({ "path": "_slots/current-focus.md", "body": "alice focus" }),
        ),
    )
    .await
    .expect("alice writes her slot");
    let personal = written["path"].as_str().expect("written path").to_owned();
    assert_ne!(
        personal, "_slots/current-focus.md",
        "per-user slots re-home the write"
    );
    call_with(
        &h.http,
        &alice,
        "memory_delete_page",
        scoped("scratch", json!({ "path": "_slots/current-focus.md" })),
    )
    .await
    .expect("alice deletes her slot");
    let rev = pre_delete_rev(&h, "scratch", &personal).await;

    for path in ["_slots/current-focus.md", personal.as_str()] {
        let out = call_with(
            &h.http,
            &alice,
            "memory_restore_page",
            scoped("scratch", json!({ "path": path, "rev": rev })),
        )
        .await;
        assert!(
            out.is_err(),
            "a non-admin operator must not restore {path}: {out:?}"
        );
    }
    assert_eq!(root_reads(&h, "scratch", &personal).await, None);

    let restored = call(
        &h.http,
        ROOT_TOKEN,
        "memory_restore_page",
        scoped("scratch", json!({ "path": personal, "rev": rev })),
    )
    .await
    .expect("root restores the personal slot");
    assert_eq!(
        restored["path"],
        personal.as_str(),
        "restored to the exact path"
    );
    assert!(
        root_reads(&h, "scratch", &personal)
            .await
            .is_some_and(|body| body.contains("alice focus"))
    );
    assert_eq!(
        root_reads(&h, "scratch", "_slots/current-focus.md").await,
        None,
        "a restore must never land on the shared slot"
    );
}

use std::fs::{self, OpenOptions};
use std::io::{self, BufRead, Write};
use std::path::PathBuf;
use std::thread;
use std::time::Duration;

fn main() {
    let codex_home = PathBuf::from(std::env::var_os("CODEX_HOME").expect("CODEX_HOME"));
    writeln!(
        OpenOptions::new()
            .create(true)
            .append(true)
            .open(codex_home.join("fake-invocations"))
            .unwrap(),
        "started"
    )
    .unwrap();
    let mode = fs::read_to_string(codex_home.join("fake-mode"))
        .unwrap_or_else(|_| "success".into());
    if mode.trim() == "sleep" {
        thread::sleep(Duration::from_secs(10));
        return;
    }
    if mode.trim() == "exit" {
        return;
    }
    if mode.trim() == "exit-nonzero" {
        std::process::exit(17);
    }
    if mode.trim() == "stderr" {
        io::stderr().write_all(&vec![b'x'; 70 * 1024]).unwrap();
        io::stderr().flush().unwrap();
        thread::sleep(Duration::from_secs(10));
        return;
    }
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let mut stdout = io::stdout();
    let initialize = lines.next().expect("initialize line").expect("initialize");
    assert!(initialize.contains("\"method\":\"initialize\""));
    match mode.trim() {
        "invalid" => writeln!(stdout, "not-json").unwrap(),
        "wrong-id" => writeln!(stdout, "{{\"jsonrpc\":\"2.0\",\"id\":99,\"result\":{{}}}}").unwrap(),
        "oversized" => writeln!(stdout, "{}", "x".repeat(257 * 1024)).unwrap(),
        _ => {
            writeln!(stdout, "{{\"jsonrpc\":\"2.0\",\"method\":\"notice\"}}").unwrap();
            writeln!(stdout, "{{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{{}}}}").unwrap();
        }
    }
    stdout.flush().unwrap();
    if !matches!(mode.trim(), "success" | "no-change") {
        thread::sleep(Duration::from_secs(10));
        return;
    }
    let initialized = lines.next().expect("initialized line").expect("initialized");
    assert!(initialized.contains("\"method\":\"initialized\""));
    let account_read = lines.next().expect("account/read line").expect("account/read");
    assert!(account_read.contains("\"method\":\"account/read\""));
    assert!(account_read.contains("\"refreshToken\":true"));
    if mode.trim() == "success" {
        let auth_path = codex_home.join("auth.json");
        let auth = fs::read_to_string(&auth_path).unwrap();
        fs::write(auth_path, auth.replace("old-token", "new-token")).unwrap();
    }
    writeln!(stdout, "{{\"jsonrpc\":\"2.0\",\"id\":2,\"result\":{{}}}}").unwrap();
    stdout.flush().unwrap();
    thread::sleep(Duration::from_secs(10));
}

//! Integration tests for `POST /admin/backup`.
//!
//! Builds a real [`AdminState`] over a tmpdir-backed store + wiki,
//! seeds a page, POSTs to `/admin/backup`, and asserts:
//! - the response Content-Type is `application/gzip`,
//! - the body is a valid gzip/tar stream,
//! - the seeded wiki file appears in the tarball at the per-project path,
//! - the seeded file's content inside the tarball matches the original body.

use ai_memory_core::{PagePath, Tier};
use ai_memory_mcp::{AdminState, admin_router};
use ai_memory_store::{DecayParams, Store};
use ai_memory_wiki::{Wiki, WritePageRequest};
use axum::body::Body;
use axum::http::{Request, StatusCode};
use flate2::read::GzDecoder;
use std::io::Read as _;
use tar::Archive;
use tempfile::TempDir;
use tower::ServiceExt;

async fn make_state(tmp: &TempDir) -> (AdminState, Store) {
    let store = Store::open(tmp.path()).unwrap();
    let wiki = Wiki::new(tmp.path(), store.writer.clone()).unwrap();
    let db_path = store.db_path().to_path_buf();
    let state = AdminState {
        ingest_metrics: std::sync::Arc::new(ai_memory_core::IngestMetrics::default()),
        mcp_metrics: std::sync::Arc::new(ai_memory_mcp::McpMetrics::default()),
        writer: store.writer.clone(),
        reader: store.reader.clone(),
        wiki,
        llm: None,
        auto_improve_require_approval: false,
        auto_improve_review_config: Default::default(),
        embedder: None,
        provider_health: ai_memory_llm::ProviderHealth::default(),
        decay_params: DecayParams::default(),
        contradiction_band_min: ai_memory_consolidate::DEFAULT_CONTRADICTION_SIM_LOW,
        contradiction_band_max: ai_memory_consolidate::DEFAULT_CONTRADICTION_SIM_HIGH,
        data_dir: tmp.path().to_path_buf(),
        db_path,
        bind: "127.0.0.1:0".to_string(),
        home_dir: None,
        bootstrap_lock: std::sync::Arc::new(tokio::sync::Mutex::new(())),
        token_pepper: None,
        active_project: ai_memory_core::ActiveProject::new(),
        scope_invalidator: None,
        trusted_proxy_identity: false,
    };
    (state, store)
}

/// Seed a page through [`Wiki::write_page`] so it lands in the correct
/// per-project directory (`<wiki>/<ws>/<proj>/<path>`), proving the
/// backup path picks up the production write layout.
async fn seed_page(state: &AdminState, store: &Store, path: &str, body: &str) {
    let ws = store
        .writer
        .get_or_create_workspace("default".to_string())
        .await
        .unwrap();
    let proj = store
        .writer
        .get_or_create_project(ws, "scratch".to_string(), None)
        .await
        .unwrap();
    state
        .wiki
        .write_page(WritePageRequest {
            workspace_id: ws,
            project_id: proj,
            path: PagePath::new(path).unwrap(),
            frontmatter: serde_json::json!({ "title": "Test" }),
            body: body.to_string(),
            tier: Tier::Semantic,
            pinned: false,
            title: Some("Test".into()),
            admission_ctx: None,
            author_id: None,
            actor: ai_memory_core::ActorContext::anonymous(),
            evidence: Vec::new(),
        })
        .await
        .unwrap();
}

#[tokio::test]
async fn backup_returns_application_gzip_content_type() {
    let tmp = TempDir::new().unwrap();
    let (state, store) = make_state(&tmp).await;
    seed_page(
        &state,
        &store,
        "concepts/karpathy.md",
        "compile not retrieve",
    )
    .await;

    let router = admin_router(state);
    let req = Request::builder()
        .method("POST")
        .uri("/admin/backup")
        .body(Body::empty())
        .unwrap();
    let resp = router.oneshot(req).await.unwrap();

    assert_eq!(resp.status(), StatusCode::OK);
    let ct = resp
        .headers()
        .get("content-type")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("");
    assert!(
        ct.contains("application/gzip"),
        "expected application/gzip content-type, got: {ct}"
    );
}

#[tokio::test]
async fn backup_body_is_valid_gzip_and_contains_seeded_page() {
    let tmp = TempDir::new().unwrap();
    let (state, store) = make_state(&tmp).await;
    let known_body = "compile-not-retrieve from Karpathy LLM wiki";
    seed_page(&state, &store, "concepts/karpathy.md", known_body).await;

    let router = admin_router(state);
    let req = Request::builder()
        .method("POST")
        .uri("/admin/backup")
        .body(Body::empty())
        .unwrap();
    let resp = router.oneshot(req).await.unwrap();
    assert_eq!(resp.status(), StatusCode::OK);

    let bytes = axum::body::to_bytes(resp.into_body(), usize::MAX)
        .await
        .unwrap();
    assert!(!bytes.is_empty(), "backup body must not be empty");

    // Decompress, list entries, and check the seeded file's content.
    let decoder = GzDecoder::new(bytes.as_ref());
    let mut archive = Archive::new(decoder);
    let mut found_page = false;
    let mut found_db = false;
    let mut page_content = String::new();
    for entry in archive.entries().expect("tarball must be readable") {
        let mut entry = entry.expect("entry must be readable");
        let path = entry.path().unwrap().to_string_lossy().into_owned();
        if path.contains("concepts/karpathy.md") {
            entry
                .read_to_string(&mut page_content)
                .expect("page entry must be readable");
            found_page = true;
        }
        if path.contains("memory.sqlite") {
            found_db = true;
        }
    }
    assert!(
        found_page,
        "tarball must contain the seeded page; no 'concepts/karpathy.md' entry found"
    );
    assert!(found_db, "tarball must contain the db snapshot");
    // Verify the page body matches what was written — confirms the backup
    // captured the per-project write-path content, not stale or wrong data.
    assert!(
        page_content.contains(known_body),
        "page content in tarball must contain the seeded body; got: {page_content:?}"
    );
}

#[tokio::test]
async fn backup_empty_store_still_succeeds() {
    // Even with no wiki pages, the backup must not return an error.
    let tmp = TempDir::new().unwrap();
    let (state, _store) = make_state(&tmp).await;

    let router = admin_router(state);
    let req = Request::builder()
        .method("POST")
        .uri("/admin/backup")
        .body(Body::empty())
        .unwrap();
