        );
        assert_eq!(auth.require_api_key().unwrap().expose_secret(), "sk-test");
        assert_eq!(
            auth.source(),
            CredentialSource::Environment {
                name: "OPENAI_API_KEY"
            }
        );
    }

    #[test]
    fn cli_override_takes_precedence() {
        let auth = ProviderAuth::required_api_key_from_env(
            "OPENAI_API_KEY",
            Some(SecretString::from("env-key")),
        )
        .with_cli_api_key_override(Some(SecretString::from("cli-key")));

        assert_eq!(auth.require_api_key().unwrap().expose_secret(), "cli-key");
        assert_eq!(auth.source(), CredentialSource::CliOverride);
    }

    #[test]
    fn optional_api_key_allows_absence() {
        let auth = ProviderAuth::optional_api_key_from_env("LLM_API_KEY", None);
        assert!(auth.optional_api_key().is_none());
        assert_eq!(auth.source(), CredentialSource::NotProvided);
    }

    #[test]
    fn openai_oauth_token_file_round_trips_path() {
        let auth = ProviderAuth::openai_oauth_token_file("/tmp/oauth_token.json");
        assert_eq!(auth.source(), CredentialSource::TokenFile);
        assert_eq!(
            auth.require_openai_oauth_token_file().unwrap(),
            Path::new("/tmp/oauth_token.json")
        );
    }

    #[test]
    fn copilot_auth_round_trips_inputs() {
        let auth = ProviderAuth::copilot(
            "/tmp/auth.json",
            Some(SecretString::from("ghu-test")),
            None,
            Some("https://api.example.test".into()),
        );
        let copilot = auth.require_copilot_auth().unwrap();
        assert_eq!(copilot.token_file, Path::new("/tmp/auth.json"));
        assert_eq!(copilot.github_token.unwrap().expose_secret(), "ghu-test");
        assert_eq!(
            copilot.api_base_url.as_deref(),
            Some("https://api.example.test")
        );
    }

    #[test]
    fn anthropic_oauth_token_round_trips_secret_and_reports_env_source() {
        let auth = ProviderAuth::anthropic_oauth_token(Some(SecretString::from("oauth-tok-test")));
        assert_eq!(
            auth.source(),
            CredentialSource::Environment {
                name: "ANTHROPIC_OAUTH_TOKEN"
            }
        );
        assert_eq!(
            auth.require_anthropic_oauth_token()
                .unwrap()
                .expose_secret(),
            "oauth-tok-test"
        );
        assert_eq!(auth.requirement(), AuthRequirement::AnthropicOAuthToken);
    }

    #[test]
    fn anthropic_oauth_token_absent_returns_not_configured() {
        let auth = ProviderAuth::anthropic_oauth_token(None);
        assert_eq!(auth.source(), CredentialSource::NotProvided);
        let err = auth.require_anthropic_oauth_token().unwrap_err();
        assert!(
            matches!(err, LlmError::NotConfigured(ref msg) if msg.contains("ANTHROPIC_OAUTH_TOKEN")),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn require_api_key_rejects_anthropic_oauth_credential() {
        let auth = ProviderAuth::anthropic_oauth_token(Some(SecretString::from("tok")));
        let err = auth.require_api_key().unwrap_err();
        assert!(
            matches!(err, LlmError::NotConfigured(ref msg) if msg.contains("anthropic-oauth token")),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn optional_api_key_returns_none_for_anthropic_oauth_credential() {
        let auth = ProviderAuth::anthropic_oauth_token(Some(SecretString::from("tok")));
        assert!(auth.optional_api_key().is_none());
    }

    #[test]
    fn codex_auth_round_trips_only_resolved_paths() {
        let auth = ProviderAuth::codex("/tmp/.codex/auth.json", "/opt/codex/bin/codex");
        let codex = auth.require_codex_auth().unwrap();

        assert_eq!(auth.requirement(), AuthRequirement::CodexAuthFile);
        assert_eq!(auth.source(), CredentialSource::TokenFile);
        assert_eq!(codex.auth_file, Path::new("/tmp/.codex/auth.json"));
        assert_eq!(codex.executable, Path::new("/opt/codex/bin/codex"));
        assert!(!format!("{codex:?}").contains("token"));
    }
}

//! Shared JSON auth-file helpers for token-backed providers.

use std::path::Path;
use std::time::{SystemTime, UNIX_EPOCH};

use serde::{Serialize, de::DeserializeOwned};

use crate::error::{LlmError, LlmResult};

pub(crate) fn load_entry<T>(path: &Path, key: &str) -> LlmResult<Option<T>>
where
    T: DeserializeOwned,
{
    if !path.exists() {
        return Ok(None);
    }
    let bytes = std::fs::read(path)
        .map_err(|e| LlmError::Auth(format!("read auth file {}: {e}", path.display())))?;
    let mut value = serde_json::from_slice::<serde_json::Value>(&bytes)
        .map_err(|e| LlmError::Auth(format!("parse auth file {}: {e}", path.display())))?;
    let Some(entry) = value.as_object_mut().and_then(|obj| obj.remove(key)) else {
        return Ok(None);
    };
    if entry.get("type").and_then(serde_json::Value::as_str) != Some("oauth") {
        return Ok(None);
    }
    serde_json::from_value::<T>(entry)
        .map(Some)
        .map_err(|e| LlmError::Auth(format!("parse {key} auth entry: {e}")))
}

pub(crate) fn save_entry<T>(path: &Path, key: &str, entry: Option<T>) -> LlmResult<()>
where
    T: Serialize,
{
    let mut root = if path.exists() {
        let bytes = std::fs::read(path)
            .map_err(|e| LlmError::Auth(format!("read auth file {}: {e}", path.display())))?;
        serde_json::from_slice::<serde_json::Value>(&bytes)
            .map_err(|e| LlmError::Auth(format!("parse auth file {}: {e}", path.display())))?
    } else {
        serde_json::json!({})
    };
    if !root.is_object() {
        return Err(LlmError::Auth(format!(
            "auth file {} must contain a JSON object",
            path.display()
        )));
    }
    let Some(obj) = root.as_object_mut() else {
        return Err(LlmError::Auth(format!(
            "auth file {} must contain a JSON object",
            path.display()
        )));
    };
    match entry {
        Some(entry) => {
            obj.insert(key.to_string(), serde_json::to_value(entry)?);
        }
        None => {
            obj.remove(key);
        }
    }
    if obj.is_empty() {
        if path.exists() {
            std::fs::remove_file(path)
                .map_err(|e| LlmError::Auth(format!("remove auth file {}: {e}", path.display())))?;
        }
        return Ok(());
    }
    write_auth_file(path, &root)
}

/// Atomic write for credential files, mirroring the canonical
/// `ai_memory_wiki::write_atomic` dance (write tmp → fsync → rename)
/// with two deliberate differences: a predictable `<name>.json.tmp`
/// sibling name, and chmod 0600 on the tempfile *before* any bytes land
/// so auth material is never group/world-readable, even transiently.
///
/// `ai-memory-llm` deliberately does not depend on `ai-memory-wiki`
/// (git2/notify are too heavy to pull in for a write helper), so this
/// stays a copy — keep it in step with the canonical implementation.
fn write_auth_file(path: &Path, value: &serde_json::Value) -> LlmResult<()> {
    use std::io::Write as _;
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)
            .map_err(|e| LlmError::Auth(format!("create auth dir {}: {e}", parent.display())))?;
    }
    let tmp = path.with_extension("json.tmp");
    let bytes = serde_json::to_vec_pretty(value)?;
    {
        let mut file = std::fs::OpenOptions::new()
            .create(true)
            .truncate(true)
            .write(true)
            .open(&tmp)
            .map_err(|e| LlmError::Auth(format!("open auth tmp {}: {e}", tmp.display())))?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt as _;
            file.set_permissions(std::fs::Permissions::from_mode(0o600))
                .map_err(|e| LlmError::Auth(format!("chmod auth tmp {}: {e}", tmp.display())))?;
        }
        file.write_all(&bytes)
            .map_err(|e| LlmError::Auth(format!("write auth tmp {}: {e}", tmp.display())))?;
        file.sync_all()
            .map_err(|e| LlmError::Auth(format!("fsync auth tmp {}: {e}", tmp.display())))?;
    }
    std::fs::rename(&tmp, path)
        .map_err(|e| LlmError::Auth(format!("rename auth file {}: {e}", path.display())))?;
    Ok(())
}

pub(crate) fn now_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
        .try_into()
        .unwrap_or(u64::MAX)
}

#[cfg(test)]
mod tests {
    use serde::{Deserialize, Serialize};

    use super::*;

    /// Mirrors the entry shape stored by `openai_oauth` / `oidc` callers.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    struct TestEntry {
        #[serde(rename = "type")]
        kind: String,
        access: String,
        refresh: String,
        expires: u64,
    }

    fn sample_entry() -> TestEntry {
        TestEntry {
            kind: "oauth".into(),
            access: "access-x".into(),
            refresh: "refresh-y".into(),
            expires: 1_700_000_000_000,
        }
    }

    #[test]
    fn round_trip_preserves_entry_fields() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("auth.json");
        save_entry(&path, "test", Some(sample_entry())).unwrap();
        let loaded = load_entry::<TestEntry>(&path, "test").unwrap();
        assert_eq!(loaded, Some(sample_entry()));
    }

    #[test]
    fn load_missing_file_returns_none() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("auth.json");
        let loaded = load_entry::<TestEntry>(&path, "test").unwrap();
        assert!(loaded.is_none());
    }

    #[test]
    fn load_malformed_json_returns_auth_error() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("auth.json");
        std::fs::write(&path, b"not json {{{").unwrap();
        let err = load_entry::<TestEntry>(&path, "test").unwrap_err();
        assert!(
            matches!(err, LlmError::Auth(ref msg) if msg.contains("parse auth file")),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn load_returns_none_when_key_is_absent() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("auth.json");
        save_entry(&path, "other", Some(sample_entry())).unwrap();
        let loaded = load_entry::<TestEntry>(&path, "test").unwrap();
        assert!(loaded.is_none());
    }

    #[test]
    fn load_returns_none_for_non_oauth_entry_type() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("auth.json");
        std::fs::write(
            &path,
            serde_json::to_vec_pretty(&serde_json::json!({
                "test": { "type": "api_key", "access": "a", "refresh": "b", "expires": 1 }
            }))
            .unwrap(),
        )
        .unwrap();
        let loaded = load_entry::<TestEntry>(&path, "test").unwrap();
        assert!(loaded.is_none(), "non-oauth entries must be ignored");
    }

    #[test]
    fn load_errors_when_oauth_entry_has_wrong_shape() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("auth.json");
        std::fs::write(
            &path,
            serde_json::to_vec_pretty(&serde_json::json!({
                "test": { "type": "oauth", "access": "a" }
            }))
            .unwrap(),
        )
        .unwrap();
        let err = load_entry::<TestEntry>(&path, "test").unwrap_err();
        assert!(
            matches!(err, LlmError::Auth(ref msg) if msg.contains("parse test auth entry")),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn save_preserves_sibling_keys() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("auth.json");
        save_entry(&path, "other", Some(sample_entry())).unwrap();
        save_entry(&path, "test", Some(sample_entry())).unwrap();
        let loaded_other = load_entry::<TestEntry>(&path, "other").unwrap();
        let loaded_test = load_entry::<TestEntry>(&path, "test").unwrap();
        assert_eq!(loaded_other, Some(sample_entry()));
        assert_eq!(loaded_test, Some(sample_entry()));
    }

    #[test]
    fn save_rejects_non_object_auth_file() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("auth.json");
        std::fs::write(&path, b"[1, 2, 3]").unwrap();
        let err = save_entry(&path, "test", Some(sample_entry())).unwrap_err();
        assert!(
            matches!(err, LlmError::Auth(ref msg) if msg.contains("must contain a JSON object")),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn removing_last_entry_deletes_file() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("auth.json");
        save_entry(&path, "test", Some(sample_entry())).unwrap();
        assert!(path.exists());
        save_entry::<TestEntry>(&path, "test", None).unwrap();
        assert!(!path.exists(), "last-entry removal deletes the auth file");
    }

    #[cfg(unix)]
    #[test]
    fn saved_file_has_owner_only_permissions() {
        use std::os::unix::fs::PermissionsExt as _;
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("auth.json");
        save_entry(&path, "test", Some(sample_entry())).unwrap();
        let mode = std::fs::metadata(&path).unwrap().permissions().mode() & 0o777;
        assert_eq!(mode, 0o600, "auth file must be owner-read/write only");
    }

    #[test]
    fn successful_save_leaves_no_tmp_file() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("auth.json");
        save_entry(&path, "test", Some(sample_entry())).unwrap();
        let tmp = path.with_extension("json.tmp");
        assert!(!tmp.exists(), "leftover tmp file: {}", tmp.display());
    }

    #[test]
    fn now_ms_returns_plausible_epoch_millis() {
        let ms = now_ms();
        assert!(ms > 1_000_000_000_000, "expected epoch millis, got {ms}");
    }
}

//! OpenAI ChatGPT/Codex OAuth provider.
//!
//! This is intentionally not a thin wrapper around `api.openai.com`: ChatGPT
//! OAuth access tokens are Codex/ChatGPT credentials, not Platform API keys.
//! Requests go to the Codex Responses backend and include the account id when
//! the token exposes one.

use std::path::{Path, PathBuf};
use std::time::Duration;

use async_trait::async_trait;
use base64::Engine as _;
use secrecy::{ExposeSecret as _, SecretString};
use serde::{Deserialize, Serialize};
use tokio::sync::Mutex;
use tracing::info;

use crate::auth_file::now_ms;
use crate::codex_responses::{CodexResponsesAuth, post_codex_responses};
use crate::error::{LlmError, LlmResult};
use crate::openai::{STRUCTURED_OUTPUT_SCHEMA_NAME, enforce_strict_object_schemas};
use crate::provider::LlmProvider;
use crate::stored_token:[REDACTED], credential_endpoint, refresh_grant};
use crate::text::truncate_with_ellipsis;
use crate::types::{ChatRequest, ChatResponse, ExtraHeaders, ReasoningEffort, Usage};

/// OpenAI OAuth issuer used by Codex/OpenCode.
pub const OPENAI_OAUTH_ISSUER: &str = "https://auth.openai.com";

/// OpenAI OAuth authorization endpoint.
pub const OPENAI_OAUTH_AUTH_URL: &str = "https://auth.openai.com/oauth/authorize";

/// OpenAI OAuth token endpoint.
pub const OPENAI_OAUTH_TOKEN_URL: &str = "https://auth.openai.com/oauth/token";

pub use crate::codex_responses::CODEX_RESPONSES_URL;

/// Public Codex/OpenCode OAuth client id.
pub const CODEX_CLIENT_ID: &str = "app_EMoamEEZ73f0CkXaXp7hrann";

/// Scopes used by Codex/OpenCode for ChatGPT sign-in.
pub const OAUTH_SCOPES: &str = "openid profile email offline_access";

/// Status code used when the Codex SSE stream carries a terminal error
/// event (`response.failed`/`response.incomplete`/`response.cancelled`
/// or a top-level `error` payload). 502 ("Bad Gateway") models the
/// situation accurately: the upstream connected, but the response it
/// sent was not a usable completion — the Codex backend, not
/// ai-memory's HTTP layer, produced the failure.
const SSE_TERMINAL_ERROR_STATUS: u16 = 502;

/// Trim length for the body field of an SSE-terminal error so we
/// don't echo a multi-megabyte upstream error into the logs / chain.
/// Matches the 1024 used by `OpenAiProvider::post` for HTTP 4xx/5xx
/// bodies — same defensive cap, same reasoning.
const SSE_ERROR_BODY_TRIM: usize = 1024;

/// OpenAI-specific claim persisted next to the shared token triple.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct OpenAiExtras {
    /// ChatGPT account/workspace id, when present in the token claims.
    #[serde(rename = "accountId", skip_serializing_if = "Option::is_none")]
    pub account_id: Option<String>,
}

/// Stored OpenAI OAuth token.
pub type OpenAiOAuthToken = [REDACTED];

impl OpenAiOAuthToken {
    /// Build a token from an OAuth token response.
    #[must_use]
    pub fn from_token_response(
        access: impl Into<String>,
        refresh: impl Into<String>,
        expires_in_secs: u64,
        id_token: [REDACTED],
        previous_account_id: Option<String>,
    ) -> Self {
        let access = access.into();
        let account_id = id_token
            .and_then(extract_account_id_from_jwt)
            .or_else(|| extract_account_id_from_jwt(&access))
            .or(previous_account_id);
        Self {
            access: SecretString::from(access),
            refresh: SecretString::from(refresh.into()),
            expires_at_ms: now_ms().saturating_add(expires_in_secs.saturating_mul(1000)),
            extra: OpenAiExtras { account_id },
        }
    }

    /// Load the OpenAI OAuth token from a shared token file.
    ///
    /// # Errors
    /// Returns [`LlmError::Auth`] when the file exists but cannot be read or
    /// parsed.
    pub fn load(path: &Path) -> LlmResult<Option<Self>> {
        Self::load_key(path, "openai")
    }

    /// Save the token into the shared token file, preserving unknown keys.
    ///
    /// # Errors
    /// Returns [`LlmError::Auth`] when the file cannot be written.
    pub fn save(&self, path: &Path) -> LlmResult<()> {
        self.save_key(path, "openai")
    }

    /// Remove the OpenAI entry from the shared token file.
    ///
    /// # Errors
    /// Returns [`LlmError::Auth`] when the file cannot be updated.
    pub fn remove(path: &Path) -> LlmResult<()> {
        Self::remove_key(path, "openai")
    }
}

/// OAuth token response returned by `auth.openai.com`.
#[derive(Debug, Deserialize)]
pub struct OpenAiOAuthTokenResponse {
    /// Access token.
    pub access_token: String,
    /// Refresh token. Refresh responses may omit it, meaning keep old refresh.
    #[serde(default)]
    pub refresh_token: [REDACTED],
    /// Expires-in seconds. Codex/OpenCode default to one hour when omitted.
    #[serde(default)]
    pub expires_in: Option<u64>,
    /// Optional ID token carrying ChatGPT account claims.
    #[serde(default)]
    pub id_token: [REDACTED],
}

/// OpenAI OAuth provider backed by the ChatGPT/Codex Responses endpoint.
pub struct OpenAiOAuthProvider {
    client: reqwest::Client,
    model: String,
    token_path: PathBuf,
    token: [REDACTED],
    timeout: Duration,
    reasoning_effort: Option<ReasoningEffort>,
    extra_headers: ExtraHeaders,
}

impl OpenAiOAuthProvider {
    /// Build a provider from an OAuth token file.
    ///
    /// # Errors
    /// Returns [`LlmError::NotConfigured`] when no token is present.
    pub fn new(token_path: PathBuf, model: impl Into<String>) -> LlmResult<Self> {
        let token = [REDACTED] {
            LlmError::NotConfigured(format!(
                "no openai-oauth token found at {}; run `ai-memory auth login openai-oauth`",
                token_path.display()
            ))
        })?;
        let client = reqwest::Client::builder()
            .redirect(crate::redirect::same_origin_redirects())
            .build()
            .map_err(LlmError::from)?;
        Ok(Self {
            client,
            model: model.into(),
            token_path,
            token: [REDACTED],
            timeout: Duration::from_secs(crate::DEFAULT_REQUEST_TIMEOUT_SECS),
            reasoning_effort: None,
            extra_headers: ExtraHeaders::default(),
        })
    }

    /// Override the per-request timeout (default
    /// [`crate::DEFAULT_REQUEST_TIMEOUT_SECS`]).
    #[must_use]
    pub fn with_timeout_secs(mut self, secs: u64) -> Self {
        self.timeout = Duration::from_secs(secs);
        self
    }

    /// Attach operator-configured headers to every chat request. The factory
    /// calls this with `ProviderConfig::extra_headers`.
    #[must_use]
    pub fn with_extra_headers(mut self, headers: ExtraHeaders) -> Self {
        self.extra_headers = headers;
        self
    }

    /// Set Responses API `reasoning.effort`. `None` omits the field so the
    /// model default applies.
    #[must_use]
    pub fn with_reasoning_effort(mut self, effort: Option<ReasoningEffort>) -> Self {
        self.reasoning_effort = effort;
        self
    }

    async fn current_token(&self) -> LlmResult<OpenAiOAuthToken> {
        let mut guard = self.token.lock().await;
        if guard.needs_refresh() {
            info!("openai-oauth token expired or near-expiry, refreshing");
            let refreshed = refresh_access_token(&self.client, &guard).await?;
            refreshed.save(&self.token_path)?;
            *guard = refreshed;
        }
        Ok(guard.clone())
    }

    async fn post(&self, body: &CodexResponsesRequest<'_>) -> LlmResult<CodexResponsesResponse> {
        let token = [REDACTED];
        post_codex_responses(
            &self.client,
            CODEX_RESPONSES_URL,
            self.timeout,
            &CodexResponsesAuth {
                access_token: [REDACTED],
                account_id: token.extra.account_id.as_deref(),
            },
            &self.extra_headers,
            body,
        )
        .await
    }
}

#[async_trait]
impl LlmProvider for OpenAiOAuthProvider {
    fn name(&self) -> &'static str {
        "openai-oauth"
    }

    fn model(&self) -> &str {
        &self.model
    }

    async fn complete(&self, request: ChatRequest) -> LlmResult<ChatResponse> {
        let response = self
            .post(&build_request(
                &self.model,
                &request,
                None,
                self.reasoning_effort,
            ))
            .await?;
        Ok(into_chat_response(response))
    }

    async fn complete_structured_raw(
        &self,
        request: ChatRequest,
        mut schema: serde_json::Value,
    ) -> LlmResult<serde_json::Value> {
        enforce_strict_object_schemas(&mut schema);
        let response_format = CodexText {
            format: CodexTextFormat::JsonSchema {
                name: STRUCTURED_OUTPUT_SCHEMA_NAME.into(),
                schema,
                strict: true,
            },
        };
        let response = self
            .post(&build_request(
                &self.model,
                &request,
                Some(response_format),
                self.reasoning_effort,
            ))
            .await?;
        let text = extract_output_text(&response).unwrap_or_default();
        serde_json::from_str::<serde_json::Value>(&text).map_err(LlmError::from)
    }
}

async fn refresh_access_token(
    client: &reqwest::Client,
    current: &OpenAiOAuthToken,
) -> LlmResult<OpenAiOAuthToken> {
    let token_endpoint =
        credential_endpoint("OpenAI OAuth token endpoint", OPENAI_OAUTH_TOKEN_URL)?;
    let token_response = refresh_grant::<OpenAiOAuthTokenResponse>(
        client,
        &token_endpoint,
        current.refresh.expose_secret(),
        CODEX_CLIENT_ID,
        "openai-oauth refresh failed",
        "Run `ai-memory auth login openai-oauth` again.",
    )
    .await?;
    Ok(OpenAiOAuthToken:[REDACTED]
        token_response.access_token,
        token_response
            .refresh_token
            .unwrap_or_else(|| current.refresh.expose_secret().to_string()),
        token_response.expires_in.unwrap_or(3600),
        token_response.id_token.as_deref(),
        current.extra.account_id.clone(),
    ))
}

pub(crate) fn build_request<'a>(
    model: &'a str,
    request: &'a ChatRequest,
    text: Option<CodexText>,
    reasoning_effort: Option<ReasoningEffort>,
) -> CodexResponsesRequest<'a> {
    let input = request
        .messages
        .iter()
        .map(|msg| CodexInputMessage {
            role: msg.role.as_str(),
            content: vec![CodexInputContent {
                kind: "input_text",
                text: &msg.content,
            }],
        })
        .collect();
    CodexResponsesRequest {
        model,
        instructions: request.system.as_deref(),
        input,
        // The ChatGPT/Codex backend currently rejects `max_output_tokens`
        // for OAuth callers on this endpoint, so rely on the server default.
        max_output_tokens: None,
        temperature: if model_uses_default_temperature(model) {
            None
        } else {
            request.temperature
        },
        store: false,
        stream: true,
        text,
        reasoning: reasoning_effort.map(|effort| CodexReasoning {
            effort: effort.openai_wire_effort(),
        }),
    }
}

pub(crate) fn parse_sse_response(body: &str) -> LlmResult<CodexResponsesResponse> {
    let mut current_event: Option<String> = None;
    let mut data_lines: Vec<&str> = Vec::new();
    let mut output_text = String::new();
    let mut completed: Option<CodexResponsesResponse> = None;

    let mut flush_event = |event: Option<&str>, data_lines: &mut Vec<&str>| -> LlmResult<()> {
        if data_lines.is_empty() {
            return Ok(());
        }
        let data = data_lines.join("\n");
        data_lines.clear();
        let trimmed = data.trim();
        if trimmed.is_empty() || trimmed == "[DONE]" {
            return Ok(());
        }

        let value = serde_json::from_str::<serde_json::Value>(trimmed)?;
        // A bare `data: {"error": {...}}` event without a `type` field
        // and without an `event:` header would otherwise fall through
        // the `_ => {}` arm and silently disappear, leaving the caller
        // with "stream closed before response.completed". Promote
        // any top-level `error` payload to a terminal error so the real
        // upstream failure reaches the caller verbatim.
        if value.get("error").is_some() {
            return Err(LlmError::Provider {
                status: SSE_TERMINAL_ERROR_STATUS,
                body: truncate_with_ellipsis(trimmed, SSE_ERROR_BODY_TRIM),
            });
        }
        let kind = value
            .get("type")
            .and_then(|v| v.as_str())
            .or(event)
            .unwrap_or_default();
        match kind {
            "response.output_text.delta" => {
                if let Some(delta) = value.get("delta").and_then(|v| v.as_str()) {
                    output_text.push_str(delta);
                }
            }
            "response.completed" => {
                let response = value.get("response").cloned().unwrap_or(value);
                completed = Some(serde_json::from_value(response)?);
            }
            "response.failed" | "response.incomplete" | "response.cancelled" | "error" => {
                return Err(LlmError::Provider {
                    status: SSE_TERMINAL_ERROR_STATUS,
                    body: truncate_with_ellipsis(trimmed, SSE_ERROR_BODY_TRIM),
                });
            }
            _ => {}
        }
        Ok(())
    };

    for line in body.lines() {
        if line.is_empty() {
            flush_event(current_event.as_deref(), &mut data_lines)?;
            current_event = None;
            continue;
        }
        if let Some(rest) = line.strip_prefix("event:") {
            current_event = Some(rest.trim().to_string());
            continue;
        }
        if let Some(rest) = line.strip_prefix("data:") {
            data_lines.push(rest.trim_start());
        }
    }
    // Final flush. A stream that ended mid-`data:` chunk leaves the
    // last partial JSON in `data_lines`; surface that as a
    // truncated-stream error so the caller doesn't see a generic
    // serde parse failure when the true cause is the upstream socket
    // closing before sending the closing `}`.
    if let Err(err) = flush_event(current_event.as_deref(), &mut data_lines) {
        return match (&err, completed.is_some()) {
            (LlmError::Serde(_), false) => Err(LlmError::UnexpectedShape(
                "openai-oauth stream truncated before final event closed (incomplete JSON payload)"
                    .into(),
            )),
            _ => Err(err),
        };
    }

    let mut response = completed.ok_or_else(|| {
        LlmError::UnexpectedShape("openai-oauth stream closed before response.completed".into())
    })?;
    if response
        .output_text
        .as_deref()
        .unwrap_or_default()
        .is_empty()
        && !output_text.is_empty()
    {
        response.output_text = Some(output_text);
    }
    Ok(response)
}

/// Models on the ChatGPT/Codex and Copilot backends that reject a
/// caller-supplied `temperature`. Shared by the `openai-oauth`, `codex`
/// and `copilot` providers.
pub(crate) fn model_uses_default_temperature(model: &str) -> bool {
    let m = model.to_ascii_lowercase();
    m.starts_with("gpt-5") || m.starts_with("gpt-6") || m.starts_with('o')
}

#[derive(Debug, Serialize)]
pub(crate) struct CodexResponsesRequest<'a> {
    model: &'a str,
    #[serde(skip_serializing_if = "Option::is_none")]
    instructions: Option<&'a str>,
    input: Vec<CodexInputMessage<'a>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    max_output_tokens: Option<u32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    temperature: Option<f32>,
    store: bool,
    pub(crate) stream: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    text: Option<CodexText>,
    #[serde(skip_serializing_if = "Option::is_none")]
    reasoning: Option<CodexReasoning>,
}

#[derive(Debug, Serialize)]
struct CodexReasoning {
    effort: ReasoningEffort,
}

#[derive(Debug, Serialize)]
struct CodexInputMessage<'a> {
    role: &'a str,
    content: Vec<CodexInputContent<'a>>,
}

#[derive(Debug, Serialize)]
struct CodexInputContent<'a> {
    #[serde(rename = "type")]
    kind: &'a str,
    text: &'a str,
}

#[derive(Debug, Serialize)]
pub(crate) struct CodexText {
    pub(crate) format: CodexTextFormat,
}

#[derive(Debug, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub(crate) enum CodexTextFormat {
    JsonSchema {
        name: String,
        schema: serde_json::Value,
        strict: bool,
    },
}

#[derive(Debug, Deserialize)]
pub(crate) struct CodexResponsesResponse {
    #[serde(default)]
    output_text: Option<String>,
    #[serde(default)]
    output: Vec<CodexOutputItem>,
    #[serde(default)]
    usage: Option<CodexUsage>,
    #[serde(default)]
    model: Option<String>,
}

#[derive(Debug, Deserialize)]
struct CodexOutputItem {
    #[serde(default)]
    content: Vec<CodexOutputContent>,
}

#[derive(Debug, Deserialize)]
struct CodexOutputContent {
    #[serde(default)]
    text: Option<String>,
}

#[derive(Debug, Deserialize)]
struct CodexUsage {
    #[serde(default)]
    input_tokens: u32,
    #[serde(default)]
    output_tokens: u32,
}

pub(crate) fn into_chat_response(response: CodexResponsesResponse) -> ChatResponse {
    let model = response
        .model
        .clone()
        .unwrap_or_else(|| "openai-oauth".into());
    ChatResponse {
        text: extract_output_text(&response).unwrap_or_default(),
        usage: response.usage.map(|u| Usage {
            input_tokens: u.input_tokens,
            output_tokens: u.output_tokens,
        }),
        model,
    }
}

pub(crate) fn extract_output_text(response: &CodexResponsesResponse) -> Option<String> {
    if let Some(text) = response
        .output_text
        .as_deref()
        .filter(|text| !text.is_empty())
    {
        return Some(text.to_string());
    }
    response
        .output
        .iter()
        .flat_map(|item| item.content.iter())
        .filter_map(|content| content.text.as_deref())
        .find(|text| !text.is_empty())
        .map(ToOwned::to_owned)
}

fn extract_account_id_from_jwt(token: &str) -> Option<String> {
    let payload = token.split('.').nth(1)?;
    let bytes = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .decode(payload)
        .ok()?;
    let value = serde_json::from_slice::<serde_json::Value>(&bytes).ok()?;
    value
        .get("chatgpt_account_id")
        .and_then(|v| v.as_str())
        .or_else(|| {
            value
                .get("https://api.openai.com/auth")
                .and_then(|v| v.get("chatgpt_account_id"))
                .and_then(|v| v.as_str())
        })
        .or_else(|| {
            value
                .get("organizations")
                .and_then(|v| v.as_array())
                .and_then(|v| v.first())
                .and_then(|v| v.get("id"))
                .and_then(|v| v.as_str())
        })
        .map(ToOwned::to_owned)
}

#[cfg(test)]
mod tests {
    use rstest::rstest;
    use serde_json::json;

    use super::*;

    #[test]
    fn token_file_preserves_unknown_entries() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("oauth_token.json");
        std::fs::write(
            &path,
            serde_json::to_vec_pretty(&json!({
                "other": { "type": "oauth", "access": "x" }
            }))
            .unwrap(),
        )
        .unwrap();
        let token = [REDACTED] {
            access: SecretString::from("access"),
            refresh: SecretString::from("refresh"),
            expires_at_ms: 1234,
            extra: OpenAiExtras {
                account_id: Some("acct".into()),
            },
        };
        token.save(&path).unwrap();
        let value =
            serde_json::from_slice::<serde_json::Value>(&std::fs::read(&path).unwrap()).unwrap();
        assert!(value.get("other").is_some());
        assert_eq!(value["openai"]["access"], "access");
        assert_eq!(value["openai"]["accountId"], "acct");
    }

    #[test]
    fn token_file_round_trips_openai_entry() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("oauth_token.json");
        let token = [REDACTED] {
            access: SecretString::from("access"),
            refresh: SecretString::from("refresh"),
            expires_at_ms: 1234,
            extra: OpenAiExtras { account_id: None },
        };
        token.save(&path).unwrap();
        let loaded = OpenAiOAuthToken:[REDACTED];
        assert_eq!(loaded.access.expose_secret(), "access");
        assert_eq!(loaded.refresh.expose_secret(), "refresh");
        assert_eq!(loaded.expires_at_ms, 1234);
        // On-disk format: `accountId` is omitted entirely when absent.
        let value =
            serde_json::from_slice::<serde_json::Value>(&std::fs::read(&path).unwrap()).unwrap();
        assert!(value["openai"].get("accountId").is_none());
    }

    #[test]
    fn token_file_ignores_non_oauth_openai_entry() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("oauth_token.json");
        std::fs::write(
            &path,
            serde_json::to_vec_pretty(&json!({
                "openai": { "type": "api", "key": "sk-test" }
            }))
            .unwrap(),
        )
        .unwrap();

        assert!(OpenAiOAuthToken:[REDACTED];
    }

    #[test]
    fn remove_deletes_only_openai_entry() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("oauth_token.json");
        std::fs::write(
            &path,
            serde_json::to_vec_pretty(&json!({
                "openai": { "type": "oauth", "access": "a", "refresh": "r", "expires": 1 },
                "other": { "type": "oauth", "access": "x" }
            }))
            .unwrap(),
        )
        .unwrap();
        OpenAiOAuthToken:[REDACTED];
        let value =
            serde_json::from_slice::<serde_json::Value>(&std::fs::read(&path).unwrap()).unwrap();
        assert!(value.get("openai").is_none());
        assert!(value.get("other").is_some());
    }

    #[cfg(unix)]
    #[test]
    fn token_file_is_mode_0600() {
        use std::os::unix::fs::PermissionsExt as _;
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("oauth_token.json");
        let token = [REDACTED] {
            access: SecretString::from("access"),
            refresh: SecretString::from("refresh"),
            expires_at_ms: 1234,
            extra: OpenAiExtras { account_id: None },
        };
        token.save(&path).unwrap();
        let mode = std::fs::metadata(&path).unwrap().permissions().mode();
        assert_eq!(mode & 0o777, 0o600);
    }

    #[test]
    fn jwt_account_id_extraction_uses_supported_fallbacks() {
        fn jwt(payload: serde_json::Value) -> String {
            let payload = base64::engine::general_purpose::URL_SAFE_NO_PAD
                .encode(serde_json::to_vec(&payload).unwrap());
            format!("x.{payload}.y")
        }
        assert_eq!(
            extract_account_id_from_jwt(&jwt(json!({ "chatgpt_account_id": "top" }))),
            Some("top".into())
        );
        assert_eq!(
            extract_account_id_from_jwt(&jwt(json!({
                "https://api.openai.com/auth": { "chatgpt_account_id": "nested" }
            }))),
            Some("nested".into())
        );
        assert_eq!(
            extract_account_id_from_jwt(&jwt(json!({ "organizations": [{ "id": "org" }] }))),
            Some("org".into())
        );
    }

    #[test]
    fn codex_request_omits_gpt6_temperature() {
        let request = ChatRequest {
            system: None,
            messages: vec![crate::types::ChatMessage::user("hello")],
            temperature: Some(0.2),
            max_tokens: 123,
        };
        let value =
            serde_json::to_value(build_request("gpt-6-luna", &request, None, None)).unwrap();
        assert!(value.get("temperature").is_none());
    }

    #[test]
    fn codex_request_moves_system_to_instructions_and_omits_gpt5_temperature() {
        let request = ChatRequest {
            system: Some("sys".into()),
            messages: vec![crate::types::ChatMessage::user("hello")],
