            max_tokens: 123,
        };
        let value = serde_json::to_value(build_request("gpt-5.5", &request, None, None)).unwrap();
        assert_eq!(value["instructions"], "sys");
        assert_eq!(value["input"][0]["content"][0]["type"], "input_text");
        assert!(value.get("max_output_tokens").is_none());
        assert!(value.get("temperature").is_none());
        assert!(value.get("reasoning").is_none());
        assert_eq!(value["store"], false);
        assert_eq!(value["stream"], true);
    }

    #[rstest]
    #[case::omitted(None, None)]
    #[case::low(Some(ReasoningEffort::Low), Some("low"))]
    #[case::persistent_clamps_max(Some(ReasoningEffort::Persistent), Some("max"))]
    fn codex_request_reasoning_effort(
        #[case] effort: Option<ReasoningEffort>,
        #[case] expected: Option<&str>,
    ) {
        let request = ChatRequest::user_prompt("hello");
        let value = serde_json::to_value(build_request("gpt-5.5", &request, None, effort)).unwrap();
        match expected {
            Some(effort) => assert_eq!(value["reasoning"]["effort"], effort),
            None => assert!(value.get("reasoning").is_none()),
        }
    }

    #[test]
    fn parse_sse_response_reconstructs_completed_payload() {
        let body = concat!(
            "event: response.output_text.delta\n",
            "data: {\"type\":\"response.output_text.delta\",\"delta\":\"hel\"}\n\n",
            "event: response.output_text.delta\n",
            "data: {\"type\":\"response.output_text.delta\",\"delta\":\"lo\"}\n\n",
            "event: response.completed\n",
            "data: {\"type\":\"response.completed\",\"response\":{\"model\":\"gpt-5.5\",\"usage\":{\"input_tokens\":12,\"output_tokens\":3},\"output\":[]}}\n\n",
            "data: [DONE]\n\n"
        );

        let response = parse_sse_response(body).unwrap();
        assert_eq!(response.model.as_deref(), Some("gpt-5.5"));
        assert_eq!(response.output_text.as_deref(), Some("hello"));
        let usage = response.usage.expect("usage from completed event");
        assert_eq!(usage.input_tokens, 12);
        assert_eq!(usage.output_tokens, 3);
    }

    #[test]
    fn parse_sse_response_surfaces_terminal_failure_events() {
        for event in [
            "response.failed",
            "response.incomplete",
            "response.cancelled",
            "error",
        ] {
            let body = format!(
                "event: {event}\n\
                 data: {{\"type\":\"{event}\",\"error\":{{\"message\":\"stream stopped\"}}}}\n\n"
            );

            let err = parse_sse_response(&body).expect_err("terminal event must fail");
            match err {
                LlmError::Provider { status, body } => {
                    assert_eq!(status, 502);
                    assert!(body.contains(event), "body should include event: {body}");
                    assert!(
                        body.contains("stream stopped"),
                        "body should include error: {body}"
                    );
                }
                other => panic!("expected provider error for {event}, got {other:?}"),
            }
        }
    }

    #[test]
    fn parse_sse_response_requires_completed_event() {
        let body = concat!(
            "event: response.output_text.delta\n",
            "data: {\"type\":\"response.output_text.delta\",\"delta\":\"partial\"}\n\n",
            "data: [DONE]\n\n",
        );

        let err = parse_sse_response(body).expect_err("missing completed event must fail");
        assert!(
            err.to_string()
                .contains("stream closed before response.completed"),
            "unexpected error: {err}"
        );
    }

    /// Audit BLOCKING fix: a `data: {"error":{...}}` event without a
    /// `type` field and without a preceding `event:` header used to
    /// fall through the kind-dispatch silently. Now any top-level
    /// `error` payload is promoted to a terminal error so the real
    /// upstream failure reaches the caller.
    #[test]
    fn parse_sse_response_promotes_top_level_error_without_event_header() {
        let body = "data: {\"error\":{\"message\":\"context length exceeded\"}}\n\n";
        let err = parse_sse_response(body)
            .expect_err("top-level error payload must surface as a terminal error");
        match err {
            LlmError::Provider { status, body } => {
                assert_eq!(status, super::SSE_TERMINAL_ERROR_STATUS);
                assert!(
                    body.contains("context length exceeded"),
                    "body must carry upstream error message: {body}"
                );
            }
            other => panic!("expected Provider error, got {other:?}"),
        }
    }

    /// Audit BLOCKING fix: a stream that ends mid-`data:` JSON (the
    /// upstream socket closes before the closing brace) used to surface
    /// as a generic serde parse error. The post-loop flush now catches
    /// that case when no `response.completed` event has arrived and
    /// emits the actionable "stream truncated" diagnostic.
    #[test]
    fn parse_sse_response_truncated_data_surfaces_as_truncated_stream() {
        // `data:` line carrying an unterminated JSON object, no blank
        // line after — the post-loop flush is what runs.
        let body = "data: {\"type\":\"response.output_text.delta\",\"delta\":\"hel";
        let err = parse_sse_response(body).expect_err("truncated stream must fail");
        assert!(
            err.to_string()
                .contains("stream truncated before final event closed"),
            "expected truncation-aware error, got: {err}"
        );
    }

    /// Empty body — no `data:` lines at all — falls through to the
    /// `completed.is_none()` branch with the original
    /// "stream closed before response.completed" error.
    #[test]
    fn parse_sse_response_empty_body_reports_no_completed_event() {
        let err = parse_sse_response("").expect_err("empty body must fail");
        assert!(
            err.to_string()
                .contains("stream closed before response.completed"),
            "expected canonical 'no completed' error, got: {err}"
        );
    }

    /// SSE spec allows an event to carry multiple `data:` lines; the
    /// parser joins them with `\n` before JSON-decoding. Exercise the
    /// continuation path so a future refactor doesn't drop it.
    #[test]
    fn parse_sse_response_handles_multi_line_data_continuation() {
        // Real upstreams sometimes split a wide JSON object across
        // multiple `data:` lines; the parser joins on '\n' before
        // serde_json parses, so a JSON value spanning newlines must
        // survive (here we exercise a JSON STRING that contains a
        // literal newline, which IS valid serde input).
        let body = concat!(
            "event: response.completed\n",
            "data: {\"type\":\"response.completed\",\"response\":{\"model\":\"gpt-5.5\",\"output_text\":\"line1\\nline2\",\"output\":[]}}\n\n",
            "data: [DONE]\n\n",
        );
        let resp = parse_sse_response(body).expect("multi-line content must parse");
        assert_eq!(resp.output_text.as_deref(), Some("line1\nline2"));
    }

    #[test]
    fn structured_request_uses_responses_json_schema_format() {
        let request = ChatRequest::user_prompt("json please");
        let text = CodexText {
            format: CodexTextFormat::JsonSchema {
                name: "Result".into(),
                schema: json!({ "type": "object", "properties": {} }),
                strict: true,
            },
        };
        let value =
            serde_json::to_value(build_request("gpt-5.5", &request, Some(text), None)).unwrap();
        assert_eq!(value["text"]["format"]["type"], "json_schema");
        assert_eq!(value["text"]["format"]["name"], "Result");
        assert_eq!(value["text"]["format"]["strict"], true);
    }

    #[test]
    fn response_text_prefers_output_text_then_output_items() {
        let direct: CodexResponsesResponse = serde_json::from_value(json!({
            "output_text": "direct",
            "output": [{ "content": [{ "text": "nested" }] }]
        }))
        .unwrap();
        assert_eq!(extract_output_text(&direct).as_deref(), Some("direct"));

        let nested: CodexResponsesResponse = serde_json::from_value(json!({
            "output": [{ "content": [{ "text": "nested" }] }]
        }))
        .unwrap();
        assert_eq!(extract_output_text(&nested).as_deref(), Some("nested"));
    }
}

//! Capacity isolation for in-process embedding inference.
//!
//! Local model inference is CPU-heavy and already parallelizes internally.
//! Letting background page writes fill every inference slot can more than
//! double interactive query latency. [`EmbeddingCapacity`] bounds total work
//! while reserving one slot for query embeddings.

use std::sync::Arc;

use async_trait::async_trait;
use tokio::sync::{OwnedSemaphorePermit, Semaphore};

use crate::{Embedder, LlmError, LlmResult};

/// Embedder wrapper that bounds inference and reserves foreground capacity.
///
/// `capacity` must be at least two. Document and generic embeddings may use
/// at most `capacity - 1` slots, so an interactive query can enter without
/// waiting for background indexing work to finish.
pub struct EmbeddingCapacity {
    inner: Arc<dyn Embedder>,
    total: Arc<Semaphore>,
    documents: Arc<Semaphore>,
}

impl EmbeddingCapacity {
    /// Wrap `inner` with a bounded scheduler.
    ///
    /// # Errors
    /// Returns [`LlmError::NotConfigured`] when fewer than two slots are
    /// requested because that cannot reserve foreground capacity.
    pub fn new(inner: Arc<dyn Embedder>, capacity: usize) -> LlmResult<Self> {
        if capacity < 2 {
            return Err(LlmError::NotConfigured(
                "embedding capacity must be at least 2".into(),
            ));
        }
        Ok(Self {
            inner,
            total: Arc::new(Semaphore::new(capacity)),
            documents: Arc::new(Semaphore::new(capacity - 1)),
        })
    }

    async fn acquire_document_capacity(
        &self,
    ) -> LlmResult<(OwnedSemaphorePermit, OwnedSemaphorePermit)> {
        let document = self
            .documents
            .clone()
            .acquire_owned()
            .await
            .map_err(|_| capacity_closed())?;
        let total = self
            .total
            .clone()
            .acquire_owned()
            .await
            .map_err(|_| capacity_closed())?;
        Ok((document, total))
    }

    async fn finish_task(
        task: tokio::task::JoinHandle<LlmResult<Vec<f32>>>,
    ) -> LlmResult<Vec<f32>> {
        task.await
            .map_err(|e| LlmError::UnexpectedShape(format!("embedding task: {e}")))?
    }
}

fn capacity_closed() -> LlmError {
    LlmError::UnexpectedShape("embedding capacity scheduler closed".into())
}

#[async_trait]
impl Embedder for EmbeddingCapacity {
    fn provider(&self) -> &'static str {
        self.inner.provider()
    }

    fn model(&self) -> &str {
        self.inner.model()
    }

    fn model_identity(&self) -> String {
        self.inner.model_identity()
    }

    fn dim(&self) -> u32 {
        self.inner.dim()
    }

    async fn embed(&self, text: &str) -> LlmResult<Vec<f32>> {
        let capacity = self.acquire_document_capacity().await?;
        let inner = Arc::clone(&self.inner);
        let text = text.to_owned();
        Self::finish_task(tokio::spawn(async move {
            let _capacity = capacity;
            inner.embed(&text).await
        }))
        .await
    }

    async fn embed_document(&self, text: &str) -> LlmResult<Vec<f32>> {
        let capacity = self.acquire_document_capacity().await?;
        let inner = Arc::clone(&self.inner);
        let text = text.to_owned();
        Self::finish_task(tokio::spawn(async move {
            let _capacity = capacity;
            inner.embed_document(&text).await
        }))
        .await
    }

    async fn embed_query(&self, text: &str) -> LlmResult<Vec<f32>> {
        let capacity = self
            .total
            .clone()
            .try_acquire_owned()
            .map_err(|_| LlmError::CapacityBusy("embedding"))?;
        let inner = Arc::clone(&self.inner);
        let text = text.to_owned();
        Self::finish_task(tokio::spawn(async move {
            let _capacity = capacity;
            inner.embed_query(&text).await
        }))
        .await
    }
}

#[cfg(test)]
mod tests {
    use std::time::Duration;

    use tokio::sync::mpsc;

    use super::*;

    struct BlockingEmbedder {
        entered: mpsc::UnboundedSender<&'static str>,
        releases: Arc<Semaphore>,
    }

    impl BlockingEmbedder {
        async fn block(&self, operation: &'static str) -> LlmResult<Vec<f32>> {
            self.entered.send(operation).unwrap();
            self.releases
                .acquire()
                .await
                .map_err(|_| capacity_closed())?
                .forget();
            Ok(vec![1.0])
        }
    }

    #[async_trait]
    impl Embedder for BlockingEmbedder {
        fn provider(&self) -> &'static str {
            "blocking"
        }

        fn model(&self) -> &str {
            "test"
        }

        fn model_identity(&self) -> String {
            "document-identity".into()
        }

        fn dim(&self) -> u32 {
            1
        }

        async fn embed(&self, _text: &str) -> LlmResult<Vec<f32>> {
            self.block("generic").await
        }

        async fn embed_document(&self, _text: &str) -> LlmResult<Vec<f32>> {
            self.block("document").await
        }

        async fn embed_query(&self, _text: &str) -> LlmResult<Vec<f32>> {
            self.block("query").await
        }
    }

    #[test]
    fn requires_a_foreground_reservation() {
        let (entered, _entered_rx) = mpsc::unbounded_channel();
        let inner = Arc::new(BlockingEmbedder {
            entered,
            releases: Arc::new(Semaphore::new(0)),
        });
        assert!(EmbeddingCapacity::new(inner, 1).is_err());
    }

    #[tokio::test]
    async fn query_enters_while_second_document_waits() {
        let (entered, mut entered_rx) = mpsc::unbounded_channel();
        let releases = Arc::new(Semaphore::new(0));
        let inner = Arc::new(BlockingEmbedder {
            entered,
            releases: Arc::clone(&releases),
        });
        let stage: Arc<dyn Embedder> = Arc::new(EmbeddingCapacity::new(inner, 2).unwrap());

        let first_document = {
            let stage = Arc::clone(&stage);
            tokio::spawn(async move { stage.embed_document("one").await })
        };
        assert_eq!(entered_rx.recv().await, Some("document"));

        let second_document = {
            let stage = Arc::clone(&stage);
            tokio::spawn(async move { stage.embed_document("two").await })
        };
        let query = {
            let stage = Arc::clone(&stage);
            tokio::spawn(async move { stage.embed_query("find it").await })
        };

        assert_eq!(
            tokio::time::timeout(Duration::from_secs(1), entered_rx.recv())
                .await
                .unwrap(),
            Some("query"),
            "the reserved query slot must remain available"
        );
        assert!(
            crate::embed_search_query(stage.as_ref(), "another query")
                .await
                .is_none(),
            "a saturated query must degrade immediately to non-vector search"
        );
        assert!(
            tokio::time::timeout(Duration::from_millis(25), entered_rx.recv())
                .await
                .is_err(),
            "the second document must wait for the document slot"
        );

        releases.add_permits(1);
        assert_eq!(
            tokio::time::timeout(Duration::from_secs(1), entered_rx.recv())
                .await
                .unwrap(),
            Some("document")
        );
        releases.add_permits(2);
        first_document.await.unwrap().unwrap();
        second_document.await.unwrap().unwrap();
        query.await.unwrap().unwrap();
    }

    #[tokio::test]
    async fn cancelled_caller_does_not_release_capacity_before_inference_finishes() {
        let (entered, mut entered_rx) = mpsc::unbounded_channel();
        let releases = Arc::new(Semaphore::new(0));
        let stage: Arc<dyn Embedder> = Arc::new(
            EmbeddingCapacity::new(
                Arc::new(BlockingEmbedder {
                    entered,
                    releases: Arc::clone(&releases),
                }),
                2,
            )
            .unwrap(),
        );

        let cancelled = {
            let stage = Arc::clone(&stage);
            tokio::spawn(async move { stage.embed_document("cancel me").await })
        };
        assert_eq!(entered_rx.recv().await, Some("document"));
        cancelled.abort();
        assert!(cancelled.await.unwrap_err().is_cancelled());

        let next = {
            let stage = Arc::clone(&stage);
            tokio::spawn(async move { stage.embed_document("wait for capacity").await })
        };
        assert!(
            tokio::time::timeout(Duration::from_millis(25), entered_rx.recv())
                .await
                .is_err(),
            "cancelled caller must not free a still-running inference slot"
        );

        releases.add_permits(1);
        assert_eq!(
            tokio::time::timeout(Duration::from_secs(1), entered_rx.recv())
                .await
                .unwrap(),
            Some("document")
        );
        releases.add_permits(1);
        next.await.unwrap().unwrap();
    }

    #[tokio::test]
    async fn generic_embedding_keeps_inner_method_semantics() {
        let (entered, mut entered_rx) = mpsc::unbounded_channel();
        let releases = Arc::new(Semaphore::new(0));
        let stage = Arc::new(
            EmbeddingCapacity::new(
                Arc::new(BlockingEmbedder {
                    entered,
                    releases: Arc::clone(&releases),
                }),
                2,
            )
            .unwrap(),
        );
        let task = tokio::spawn(async move { stage.embed("generic input").await });
        assert_eq!(entered_rx.recv().await, Some("generic"));
        releases.add_permits(1);
        task.await.unwrap().unwrap();
    }

    #[test]
    fn delegates_embedding_identity() {
        let (entered, _entered_rx) = mpsc::unbounded_channel();
        let stage = EmbeddingCapacity::new(
            Arc::new(BlockingEmbedder {
                entered,
                releases: Arc::new(Semaphore::new(0)),
            }),
            2,
        )
        .unwrap();
        assert_eq!(stage.provider(), "blocking");
        assert_eq!(stage.model(), "test");
        assert_eq!(stage.model_identity(), "document-identity");
        assert_eq!(stage.dim(), 1);
    }
}

//! A2 extractive tier-down, end to end through a real Store + Wiki.
//!
//! The invariants this file guards (docs/design-memory-aging.md §A2):
//!
//! 1. **Flag OFF = today's behaviour.** A cold episodic page is EVICTED
//!    (tombstoned), not compacted — an upgrade surprises no one.
//! 2. **Flag ON = compaction.** The same page is tiered down: the new latest
//!    version keeps its L0 abstract, an L1 summary and the L2 keep-tokens, drops
//!    the prose, sets the V65 `compacted_at` marker and the `compacted: true`
//!    frontmatter mirror, and is reported under `SweepReport.compacted`, not
//!    `evicted`.
//! 3. **Keep-tokens survive.** A file path + error code + URL seeded in the body
//!    are present in the compacted body.
//! 4. **Reversible.** The pre-compaction full body stays reachable via the
//!    supersession chain and is recoverable with `restore_page_from_checkpoint`.
//! 5. **No re-compaction.** A second sweep does not re-compact an
//!    already-compacted page, and the curator does not re-report it as cold.
//! 6. **Only episodic.** Pinned / semantic / procedural pages never compact.

use ai_memory_consolidate::ObservationRetention;
use ai_memory_consolidate::{
    CuratorParams, run_curator_report, run_sweep_with_compaction, run_sweep_with_options,
};
use ai_memory_core::{ActorContext, PageId, PagePath, ProjectId, Tier, WorkspaceId};
use ai_memory_store::{DecayParams, Store};
use ai_memory_wiki::{Wiki, WritePageRequest};
use rusqlite::params;
use tempfile::TempDir;

const DAY_US: i64 = 86_400_000_000;

struct Fixture {
    tmp: TempDir,
    store: Store,
    wiki: Wiki,
    ws: WorkspaceId,
    proj: ProjectId,
}

async fn seed_fixture() -> Fixture {
    let tmp = TempDir::new().unwrap();
    let store = Store::open(tmp.path()).unwrap();
    let ws = store
        .writer
        .get_or_create_workspace("default")
        .await
        .unwrap();
    let proj = store
        .writer
        .get_or_create_project(ws, "scratch", None)
        .await
        .unwrap();
    // The reader is required by the sweep's `evict_page_if_latest` guard; the
    // compaction path also reads the page body back through the wiki.
    let wiki = Wiki::new(tmp.path(), store.writer.clone())
        .unwrap()
        .with_store_reader(store.reader.clone());
    Fixture {
        tmp,
        store,
        wiki,
        ws,
        proj,
    }
}

async fn write(
    fx: &Fixture,
    path: &str,
    title: &str,
    tier: Tier,
    pinned: bool,
    body: &str,
) -> PageId {
    fx.wiki
        .write_page(WritePageRequest {
            workspace_id: fx.ws,
            project_id: fx.proj,
            path: PagePath::new(path).unwrap(),
            frontmatter: serde_json::json!({"title": title}),
            body: body.to_string(),
            tier,
            pinned,
            title: Some(title.to_string()),
            admission_ctx: None,
            author_id: None,
            actor: ActorContext::anonymous(),
            evidence: Vec::new(),
        })
        .await
        .unwrap()
}

/// Push the current `is_latest` version of `path` back in time so it scores as
/// cold. Mirrors the aux-connection trick the other sweep/curator tests use.
fn backdate_latest(fx: &Fixture, path: &str, days: i64) {
    let conn = rusqlite::Connection::open(fx.tmp.path().join("db/memory.sqlite")).unwrap();
    conn.pragma_update(None, "busy_timeout", 5_000).unwrap();
    let updated_at = jiff::Timestamp::now().as_microsecond() - days * DAY_US;
    conn.execute(
        "UPDATE pages SET created_at = ?1, updated_at = ?1 \
         WHERE workspace_id = ?2 AND project_id = ?3 AND path = ?4 AND is_latest = 1",
        params![updated_at, fx.ws.as_bytes(), fx.proj.as_bytes(), path,],
    )
    .unwrap();
}

fn expire_latest(fx: &Fixture, path: &str) {
    let conn = rusqlite::Connection::open(fx.tmp.path().join("db/memory.sqlite")).unwrap();
    conn.pragma_update(None, "busy_timeout", 5_000).unwrap();
    conn.execute(
        "UPDATE pages SET expires_at = 1 \
         WHERE workspace_id = ?1 AND project_id = ?2 AND path = ?3 AND is_latest = 1",
        params![fx.ws.as_bytes(), fx.proj.as_bytes(), path],
    )
    .unwrap();
}

/// The `compacted_at` marker on the current latest version of `path`, and its
/// body, straight from SQLite.
fn latest_marker_and_body(fx: &Fixture, path: &str) -> (Option<i64>, String) {
    let conn = rusqlite::Connection::open(fx.tmp.path().join("db/memory.sqlite")).unwrap();
    conn.query_row(
        "SELECT compacted_at, body FROM pages \
         WHERE workspace_id = ?1 AND project_id = ?2 AND path = ?3 AND is_latest = 1",
        params![fx.ws.as_bytes(), fx.proj.as_bytes(), path],
        |row| Ok((row.get(0)?, row.get(1)?)),
    )
    .unwrap()
}

/// Every historical (superseded) body for `path`, oldest first — the
/// supersession chain the reversibility guarantee rests on.
fn superseded_bodies(fx: &Fixture, path: &str) -> Vec<String> {
    let conn = rusqlite::Connection::open(fx.tmp.path().join("db/memory.sqlite")).unwrap();
    let mut stmt = conn
        .prepare(
            "SELECT body FROM pages \
             WHERE workspace_id = ?1 AND project_id = ?2 AND path = ?3 AND is_latest = 0 \
             ORDER BY created_at",
        )
        .unwrap();
    let rows = stmt
        .query_map(params![fx.ws.as_bytes(), fx.proj.as_bytes(), path], |row| {
            row.get::<_, String>(0)
        })
        .unwrap();
    rows.map(Result::unwrap).collect()
}

const COLD_DAYS: i64 = 400;

/// Test 1: with the flag OFF the sweep evicts a cold episodic page exactly as it
/// always has — no compaction, no upgrade surprise.
#[tokio::test]
async fn flag_off_evicts_cold_episodic_page_unchanged() {
    let fx = seed_fixture().await;
    let id = write(
        &fx,
        "sessions/old.md",
        "Old Session",
        Tier::Episodic,
        false,
        "a long prose body about a debugging session that nobody reopened",
    )
